add_filter( 'the_title', 'perfectpixel_capitalize_product_title', 10, 2 );

function perfectpixel_capitalize_product_title( $title, $post_id = 0 ) {
	if ( is_admin() || ! $post_id || 'product' !== get_post_type( $post_id ) ) {
		return $title;
	}
	if ( 'words' === '{{title_case_mode}}' ) {
		return mb_convert_case( $title, MB_CASE_TITLE, 'UTF-8' );
	}
	return mb_strtoupper( mb_substr( $title, 0, 1, 'UTF-8' ), 'UTF-8' ) . mb_substr( $title, 1, null, 'UTF-8' );
}
